#!/usr/bin/env python3
"""Deterministic plan generator. No subprocesses, device access, or file writes."""
import argparse,json
p=argparse.ArgumentParser(description=__doc__);p.add_argument('action',choices=['install','uninstall']);a=p.parse_args()
install=['Verify authorized root ADB, Android 14 ARM64, enforcing SELinux and read-only system/product; establish independent recovery access.', 'Review every reference template and trust the complete root-owned non-writable ancestor chain; do not reuse a world-writable boot parent.', 'Obtain and verify pinned Magisk prerequisites and the matching runit executables AND librunit.so; inspect ELF dependencies; no binaries are supplied.', 'Before a maintenance start, privately capture pristine live kernel policy and its checksum on the actual target; never capture an already patched policy as original.', 'Archive only owned scripts and metadata privately; separately preserve the target policy under explicit owner control; record existing mounts, services and labels.', 'Review bounded startup, shutdown and failure-lock changes on a sacrificial device; choose a verified local policy pin; never use an example checksum.', 'Stage reviewed root-owned scripts privately; leave run/disable-boot and services/magisk/down in place until a separately authorized maintenance window.', 'Integrate the documented standard Android boot receiver or another verified root-owned boot trigger; do not require an unrelated application or copy its private ADB key.', 'Only with separate deployment approval: start/validate the staged service and explicitly enable the selected boot trigger; verify grants individually in Manager.']
uninstall=['Obtain separate approval and independent root ADB recovery; record ownership, hashes, mount namespace and original service state.', 'Disable only the added boot launch and Magisk service; preserve all unrelated boot/network functionality.', 'Request graceful service shutdown only in an approved maintenance window; verify overlay, daemon and runtime removal plus exact original local kernel policy restoration.', 'If cleanup is incomplete, retain failure lock and backups and stop; never force-unmount or delete a mounted upper/work directory.', 'After verified cleanup, restore only this integration\'s known original hook bytes and remove only manifest-owned staged files; retain Manager, app data, grants and unrelated services unless separately authorized.']
print(json.dumps({'schema':1,'action':a.action,'status':'EXPERIMENTAL_PLAN_ONLY','executes_device_changes':False,'deployment_requires_separate_approval':True,'steps':install if a.action=='install'else uninstall},indent=2))
